const craftingTableItemName = normalizeItemName('crafting_table');
const oakPlanksItemName = normalizeItemName('oak_planks');

async function craftCraftingTable() {
  const oakLogs = bot.inventory.items().find(i => i.name === normalizeItemName('oak_log'));
  if (!oakLogs) {
    console.error('No oak logs found in inventory');
    return;
  }

  const oakPlanksCount = 4;

  if (oakLogs.count < oakPlanksCount) {
    console.error('Not enough oak logs to craft oak planks');
    return;
  }

  await bot.craft(4, [oakLogs]);

  const oakPlanks = bot.inventory.items().find(i => i.name === oakPlanksItemName);
  if (!oakPlanks) {
    console.error('No oak planks found in inventory');
    return;
  }

  const craftingTableCount = 1;

  if (oakPlanks.count < oakPlanksCount) {
    console.error('Not enough oak planks to craft a crafting table');
    return;
  }

  await bot.craft(craftingTableCount, [oakPlanks, oakPlanks, oakPlanks, oakPlanks]);
}

craftCraftingTable();
